import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

export default function getDealToursCategories() {
    const res = fetch(
        `${apiv2Base()}/b2c/getcategorylist?columns[]=id&columns[]=name&columns[]=tour_count&columns[]=slug&columns[]=promotions&hasActivity=false`,
        {
            method: "GET",
            headers: {
            ...apiv2ServerHeaders(),
            "Content-type": "application/json",
        },
            cache: "force-cache"
        })
        .then((res) => res.json());

    return res;
}
