export default function ToursSkeleton() {
  return (
    <div
      className="tw-flex tw-flex-nowrap tw-items-stretch tw-gap-3"
      style={{ overflowX: "auto" }}
    >
      {[...Array(5)].map((x, i) => (
        <div
          key={i}
          className="tw-w-1/2 tw-shrink-0 sm:tw-w-1/3 md:tw-w-1/5"
        >
          <div className="tw-h-full tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white">
            <div className="tw-h-[120px] tw-w-full tw-animate-pulse tw-bg-[#e6e2ee]" />
            <div className="tw-p-3">
              <div className="tw-h-3.5 tw-w-full tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
              <div className="tw-mt-4 tw-flex tw-items-end tw-justify-between">
                <div className="tw-h-3 tw-w-2/3 tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
                <div className="tw-space-y-1.5">
                  <div className="tw-h-3 tw-w-12 tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
                  <div className="tw-ml-auto tw-h-3 tw-w-8 tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
                </div>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
