/*
 * apiv2 → apiv3 taşıma katmanı için bağlam-duyarlı yardımcılar.
 *
 * Eski apiv2 (Symfony) uçları apiv3'te /apiv2/* altında yeniden kuruldu. Bazı servisler hem
 * sunucu (RSC) hem tarayıcı ('use client') tarafından çağrılıyor:
 *  - Sunucuda: apiv3'e doğrudan gidilir ve X-App-Token (sunucu sırrı) eklenir.
 *  - Tarayıcıda: token sızdırılamaz → /api/apiv2 proxy'si (route handler) üzerinden gidilir;
 *    proxy X-App-Token'ı sunucu tarafında enjekte eder.
 */

const isServer = (): boolean => typeof window === "undefined";

/** apiv2 path'i için taban URL (eski `${APIV2_URL}/rest` yerine). Path'i bunun ardına ekle. */
export function apiv2Base(): string {
    return isServer() ? `${process.env.NEXT_PUBLIC_APIV3_URL}/apiv2` : `/api/apiv2`;
}

/** Sunucuda X-App-Token başlığı; tarayıcıda boş (proxy ekler). headers objesine yay. */
export function apiv2ServerHeaders(): Record<string, string> {
    return isServer() ? { "X-App-Token": process.env.APIV3_APP_TOKEN as string } : {};
}
