import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

export default function getDealTours({
  promotionType,
  category,
  pageSize,
  currency,
}: {
  promotionType: string;
  category: string;
  pageSize: number;
  currency: string;
}) {
  var categoryString = "";

  if (category !== "") categoryString = "&categories[]=" + category;

  var url =
    `${apiv2Base()}/b2c/tours/search?filters=id,name,media.collection_name,media.high,slug,category.name,promotion,rating,currency,price,old_price,reviews_count,duration,image&destination=global&order=promotions_value&order_dir=desc&page_size=${pageSize}&pax=2&activeCurrency=${currency}&price[]=0&price[]=25000&duration[]=1&duration[]=30&promotion_type=${promotionType}${categoryString}`;


  const res = fetch(url, {
    method: "GET",
    headers: {
            ...apiv2ServerHeaders(),
            "Content-type": "application/json",
          },
    cache: "no-store",
  }).then((res) => res.json());

  return res;
}
